def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    pts=set((r,c) for r in range(H) for c in range(W) if g[r][c]==4)
    def mark(r,c):
        if g[r][c]!=5: return
        hor=any((r,x) in pts for x in range(c)) and any((r,x) in pts for x in range(c+1,W))
        ver=any((y,c) in pts for y in range(r)) and any((x,c) in pts for x in range(r+1,H))
        if hor or ver: g[r][c]=3
    for r in range(H):
        for c in range(W): mark(r,c)
    return g
